import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, mkdirSync, renameSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { gzipSync, gunzipSync } from "node:zlib";
export const directory = import.meta.dir;
export const sha = (v: any) => createHash("sha256").update(v).digest("hex");
export const digest = (v: any) =>
    sha(JSON.stringify(v, (_k, x) => (x instanceof Map || x instanceof Set ? [...x] : x)));
export const read = (f: string) =>
    JSON.parse(
        (f.endsWith(".gz")
            ? gunzipSync(readFileSync(join(directory, f)))
            : readFileSync(join(directory, f))
        ).toString(),
    );
export function save(f: string, value: any) {
    const path = join(directory, f);
    assert(!existsSync(path), "Preserve existing output: " + f);
    mkdirSync(dirname(path), { recursive: true });
    const raw = Buffer.from(JSON.stringify(value) + "\n"),
        bytes = f.endsWith(".gz") ? gzipSync(raw) : raw;
    writeFileSync(path + ".pending", bytes);
    renameSync(path + ".pending", path);
    writeFileSync(
        path + ".receipt",
        JSON.stringify({
            file: f,
            sha256: sha(bytes),
            rawSha256: sha(raw),
            qualityPassed: value.qualityPassed ?? null,
        }) + "\n",
    );
}

