import { getUpgradePoints } from "./sources/common/src/doctrines/doctrine_properties";
import assert from "node:assert/strict";
import { creatureInfo } from "./sources/common/src/ai/setup/creature_score";
import { getRankedAiProfile } from "./sources/server/src/api/game/v1/ranked_ai_profile";

/** Recompute every candidate decision using the authoritative draft policy's functions. */
export function withServingDraftParity(
    research: any,
    doctrine: number,
    receipts: any[],
    synergyVariants: any,
    contextual = true,
) {
    const policy = getRankedAiProfile("v0.8").draftPolicy;
    let consumed = false,
        contextualConsumed = false;
    assert(policy.contextualDraft, "Missing adopted contextual head");
    const fullContext = (context: any) => ({ ...context, synergyVariants, budget: getUpgradePoints(doctrine) });
    const finish = (kind: string, context: any, preferred: any, alternative: any, level: number, actual: number) => {
        const decision = policy.doctrineDraft!.choose(doctrine, {
            context,
            preferred,
            alternative,
            level,
            overrideUsed: consumed,
        });
        assert.equal(actual, decision.choice, "Research and serving draft choice differ");
        consumed ||= decision.consumeOverride;
        receipts.push({
            kind,
            level,
            preferred: preferred.id,
            choice: actual,
            consumeOverride: decision.consumeOverride,
        });
        return actual;
    };
    return {
        bundle(bundles: any[], context: any, preferred: number) {
            assert.equal(
                preferred,
                policy.pickBundle(bundles, context.artifactFitVersion, context.scouting),
                "Serving base bundle differs",
            );
            const rest = bundles.map((bundle, id) => ({ bundle, id })).filter((x) => x.id !== preferred);
            const alt = rest.length
                ? rest[
                      policy.pickBundle(
                          rest.map((x) => x.bundle),
                          context.artifactFitVersion,
                          context.scouting,
                      )
                  ]
                : undefined;
            const base = finish(
                "bundle",
                context,
                { id: preferred, creatureIds: bundles[preferred].slice(0, 2), tier1ArtifactId: bundles[preferred][2] },
                alt ? { id: alt.id, creatureIds: alt.bundle.slice(0, 2), tier1ArtifactId: alt.bundle[2] } : undefined,
                0,
                research.bundle(bundles, context, preferred),
            );
            if (!contextual) return base;
            const chosen = policy.contextualDraft!.bundle(bundles, base, fullContext(context), contextualConsumed);
            contextualConsumed ||= chosen.consumeOverride;
            receipts.at(-1).contextual = {
                base,
                choice: chosen.choice,
                consumeOverride: chosen.consumeOverride,
                consumed: contextualConsumed,
                context: fullContext(context),
            };
            return chosen.choice;
        },
        creature(available: number[], context: any, preferred: number) {
            const level = creatureInfo(preferred)?.level ?? 4;
            const choose = (pool: number[]) =>
                policy.pickCreature(
                    level,
                    pool,
                    context.ownCreatureIds,
                    context.knownOpponentCreatureIds,
                    context.tier1ArtifactId,
                    context.scouting.map,
                    context.tier2ArtifactId,
                    context.artifactFitVersion,
                    context.scouting,
                );
            assert.equal(preferred, choose(available), "Serving base creature differs");
            const alt = choose(available.filter((x) => x !== preferred));
            const base = finish(
                "creature",
                context,
                { id: preferred, creatureIds: [preferred] },
                alt === undefined ? undefined : { id: alt, creatureIds: [alt] },
                level,
                research.creature(available, context, preferred),
            );
            if (!contextual) return base;
            const chosen = policy.contextualDraft!.creature(
                available,
                base,
                fullContext(context),
                level,
                contextualConsumed,
            );
            contextualConsumed ||= chosen.consumeOverride;
            receipts.at(-1).contextual = {
                base,
                choice: chosen.choice,
                consumeOverride: chosen.consumeOverride,
                consumed: contextualConsumed,
                context: fullContext(context),
            };
            return chosen.choice;
        },
    };
}

import assert from "node:assert/strict";
import {
    playRankedDraftGame,
    rankedDraftStrengthCandidate,
    permuteRankedDraftSeed,
} from "./sources/common/src/simulation/ranked_draft_eval";
import { createLockedDoctrineDraftResearchChoices } from "./sources/common/src/simulation/v0_9/doctrine_draft_checkpoint";
import { synergyVariantsForSeed } from "./sources/common/src/synergies/synergy_properties";
import { getUpgradePoints } from "./sources/common/src/doctrines/doctrine_properties";
import { creatureInfo, creatureIdForName } from "./sources/common/src/ai/setup/creature_score";
import { FightStateManager } from "./sources/common/src/fights/fight_state_manager";
import { ToFactionName } from "./sources/common/src/factions/faction_type";
import { createPlacementSetupDecisionContext } from "./sources/common/src/ai/setup/setup_strategy";
import { getRankedAiProfile } from "./sources/server/src/api/game/v1/ranked_ai_profile";
import { amountForCreatureExperienceBudget } from "./sources/server/src/simulation/creature_lookup";
import { withRankedDraftPrivateSetupVisibility } from "./sources/common/src/simulation/ranked_draft_setup_visibility";
import { profiles } from "./profiles";
import { withServingDraftParity } from "./draft-parity";
import { prepareNative } from "./native";
import { publicSetupInput, responseScenarios, type PublicSetupInput } from "./plan";

creatureInfo(1);
FightStateManager.getInstance();
const doctrineName = (d: number) => ({ 1: "three-reveals", 2: "see-all", 3: "see-none" })[d] as any;
const genome = rankedDraftStrengthCandidate(profiles.candidate.draftBase);
export function draft(task: any) {
    const variants = synergyVariantsForSeed(`ranked-draft-${permuteRankedDraftSeed(task.seed + 1)}`);
    const receipts: any[][] = [[], []],
        decisions: any[][] = [[], []];
    const choices = [task.d1, task.d2].map((d, i) =>
        withServingDraftParity(
            createLockedDoctrineDraftResearchChoices({
                doctrine: doctrineName(d),
                genome,
                synergyVariants: variants,
                onDecision: (x) => decisions[i].push(x),
            }),
            d,
            receipts[i],
            variants,
        ),
    );
    let config: any;
    const stop = new Error("Draft capture");
    try {
        playRankedDraftGame(
            genome,
            genome,
            {
                gamesPerOpponent: 8,
                baseSeed: task.seed,
                mapTypes: [task.map],
                fightProfile: "a19",
                maxLaps: 256,
                liveDraftRules: true,
                sideBoard: true,
                deterministicSearch: true,
                liveSynergyVariants: true,
                tacticalSplits: false,
                candidateSetupPolicySpec: profiles.candidate.setup,
                opponentSetupPolicySpec: profiles.opponent.setup,
                candidateDoctrinePolicy: doctrineName(task.d1),
                opponentDoctrinePolicy: doctrineName(task.d2),
            },
            task.pickOrder ? 2 : 0,
            0,
            {
                liveSequentialBundles: true,
                researchCandidateDraftChoices: choices[0],
                researchOpponentDraftChoices: choices[1],
                researchCandidateTier2Choice: (offered, own, context, preferred) => {
                    assert.equal(
                        getRankedAiProfile("v0.8").setupPolicy.pickArtifactT2(offered, own, context),
                        preferred,
                    );
                    assert.equal(context.decisionPhase, "tier2-artifact");
                    assert.equal(context.opponentRosterVisibility, "partial");
                    return preferred;
                },
                matchRunner: (c) => {
                    config = c;
                    throw stop;
                },
            },
        );
    } catch (e) {
        if (e !== stop) throw e;
    }
    assert(config);
    assert.deepEqual(config.synergyVariants, variants);
    const candidateTeam = task.pickOrder ? 1 : 2;
    assert.equal(config[candidateTeam === 2 ? "greenDoctrine" : "redDoctrine"], task.d1);
    config = {
        ...config,
        greenVersion: "v0.8",
        redVersion: "v0.8",
        sideOrientedPlacement: true,
        placementAugmentTiming: "setup-before-placement",
        searchOfflineDeterministicWork: true,
        greenTacticalSplitStacks: [],
        redTacticalSplitStacks: [],
    };
    return { config, candidateTeam, receipts, decisions };
}

export function seatedDraft(drafted: any, flip: boolean) {
    const config = withRankedDraftPrivateSetupVisibility(structuredClone(drafted.config));
    if (flip) {
        [config.roster, config.redRoster] = [config.redRoster, config.roster];
        for (const suffix of [
            "Doctrine",
            "Augments",
            "ArtifactT1",
            "ArtifactT2",
            "Synergies",
            "TacticalSplitStacks",
            "PublicOpponentCreatures",
            "RevealedCreatures",
        ])
            [config["green" + suffix], config["red" + suffix]] = [config["red" + suffix], config["green" + suffix]];
    }
    return { config, candidateTeam: flip ? 3 - drafted.candidateTeam : drafted.candidateTeam };
}

export function publicInputForDraft(drafted: any, flip: boolean): PublicSetupInput {
    const { config: c, candidateTeam: team } = seatedDraft(drafted, flip);
    const own = team === 2 ? "green" : "red";
    const ids = (r: any[]) => r.map((u) => creatureIdForName(u.creatureName)!);
    return publicSetupInput(
        ids(c[team === 2 ? "roster" : "redRoster"]),
        getUpgradePoints(c[own + "Doctrine"]),
        team,
        createPlacementSetupDecisionContext({
            publicOpponentCreatureIds: ids(c[team === 2 ? "redRoster" : "roster"]),
            opponentRosterVisibility: "complete",
            gridType: c.gridType,
            gridSize: 16,
            ownDoctrine: c[own + "Doctrine"],
            ownArtifactIds: [c[own + "ArtifactT1"], c[own + "ArtifactT2"]],
            synergyVariants: c.synergyVariants,
        }),
    );
}

export function actualOpening(
    drafted: any,
    seed: number,
    flip: boolean,
    ownPlan = 0,
    incumbentSpending = false,
    matchedGeometry?: any,
) {
    const { config, candidateTeam } = seatedDraft(drafted, flip);
    const opened = prepareNative(config, seed, candidateTeam, { ownPlan, incumbentSpending, matchedGeometry });
    assert.deepEqual(opened.publicPlans[candidateTeam].input, publicInputForDraft(drafted, flip));
    return { ...opened, candidateTeam };
}

export function hypotheticalConfig(input: PublicSetupInput, response: number, seed: number) {
    const h = responseScenarios(input)[response];
    assert(h);
    const spec = (ids: readonly number[]) =>
        ids.map((id) => {
            const info = creatureInfo(id)!;
            return {
                faction: ToFactionName[info.faction],
                creatureName: info.name,
                level: info.level,
                size: info.footprintWidth,
                amount: amountForCreatureExperienceBudget(id, 1000, 10),
            };
        });
    const own = input.physicalTeam === 2 ? "green" : "red",
        enemy = own === "green" ? "red" : "green";
    const ownRoster = spec(input.ownCreatureIds),
        enemyRoster = spec(input.context.publicOpponentCreatureIds);
    const c: any = {
        greenVersion: "v0.8",
        redVersion: "v0.8",
        seed,
        gridType: input.context.gridType,
        maxLaps: 256,
        roster: own === "green" ? ownRoster : enemyRoster,
        redRoster: own === "green" ? enemyRoster : ownRoster,
        sideOrientedPlacement: true,
        searchOfflineDeterministicWork: true,
        placementAugmentTiming: "setup-before-placement",
        greenTacticalSplitStacks: [],
        redTacticalSplitStacks: [],
        greenAugments: [],
        redAugments: [],
        greenSynergies: [],
        redSynergies: [],
        synergyVariants: input.context.synergyVariants,
    };
    c[own + "Doctrine"] = input.context.ownDoctrine;
    c[enemy + "Doctrine"] = h.doctrine;
    c[own + "ArtifactT1"] = input.context.ownArtifactIds![0];
    c[own + "ArtifactT2"] = input.context.ownArtifactIds![1];
    c[enemy + "ArtifactT1"] = h.artifactT1;
    c[enemy + "ArtifactT2"] = h.artifactT2;
    c[own + "RevealedCreatures"] = [...input.context.publicOpponentCreatureIds];
    c[enemy + "RevealedCreatures"] = [...input.ownCreatureIds];
    c[own + "PublicOpponentCreatures"] = [...input.context.publicOpponentCreatureIds];
    c[enemy + "PublicOpponentCreatures"] = [...input.ownCreatureIds];
    return { config: c, response: h };
}

export function searchOpening(input: PublicSetupInput, response: number, seed: number, ownPlan: number) {
    const h = hypotheticalConfig(input, response, seed);
    const opened = prepareNative(h.config, seed, input.physicalTeam, { ownPlan, opponentPlan: h.response.plan });
    assert.deepEqual(opened.publicPlans[input.physicalTeam].input, input);
    return { ...opened, candidateTeam: input.physicalTeam };
}

import assert from "node:assert/strict";
import { creatureInfo } from "./sources/common/src/ai/setup/creature_score";
import type { ISetupAugmentChoice } from "./sources/common/src/ai/setup/setup_ship";
import {
    createPlacementSetupDecisionContext,
    type IPlacementSetupDecisionContext,
} from "./sources/common/src/ai/setup/setup_strategy";
import type { ITacticalSplitUnit } from "./sources/common/src/ai/tactical_split_placement";
import { planA19SupportSplits } from "./sources/common/src/ai/support_setup";
import type { A19SupportSplitPlan } from "./sources/common/src/ai/healer_support_setup";

export const PLAN_IDS = [
    "current",
    "support-halves",
    "support-singles",
    "mobility-screen",
    "magic-control",
    "physical-pressure",
] as const;
export type PlanId = (typeof PLAN_IDS)[number];
export const FREE_PLAN_INDICES = [0, 1, 2] as const;
export const SEARCH_MARGIN = 0.03;
const KINDS = ["Placement", "Armor", "Might", "Empower", "Sniper", "Movement"] as const;
const CAPS = { Placement: 2, Armor: 3, Might: 3, Empower: 3, Sniper: 3, Movement: 2 };
export type SplitMode = "native" | "halves" | "singles" | "concentrated";
export interface SetupPlan {
    id: PlanId;
    augments: ISetupAugmentChoice[];
    splitMode: SplitMode;
    spendChanged: boolean;
}
export interface PublicSetupInput {
    ownCreatureIds: number[];
    budget: number;
    physicalTeam: number;
    context: Readonly<IPlacementSetupDecisionContext>;
}

export function publicSetupInput(
    own: readonly number[],
    budget: number,
    team: number,
    raw: Readonly<IPlacementSetupDecisionContext>,
): PublicSetupInput {
    assert.equal(raw.decisionPhase, "placement");
    assert.equal(raw.opponentRosterVisibility, "complete");
    assert([5, 6, 7].includes(budget));
    assert([1, 2].includes(team));
    assert.equal(new Set(own).size, 6);
    assert.equal(new Set(raw.publicOpponentCreatureIds).size, 6);
    assert([...own, ...raw.publicOpponentCreatureIds].every((id) => creatureInfo(id)));
    assert(own.every((id) => !raw.publicOpponentCreatureIds.includes(id)));
    assert.equal(raw.ownArtifactIds?.length, 2);
    assert(raw.synergyVariants);
    assert([1, 2, 3].includes(raw.ownDoctrine!));
    return {
        ownCreatureIds: [...own],
        budget,
        physicalTeam: team,
        context: createPlacementSetupDecisionContext({
            publicOpponentCreatureIds: [...raw.publicOpponentCreatureIds],
            opponentRosterVisibility: "complete",
            gridType: raw.gridType,
            gridSize: raw.gridSize,
            ownDoctrine: raw.ownDoctrine,
            ownArtifactIds: [...raw.ownArtifactIds!],
            synergyVariants: { ...raw.synergyVariants! },
        }),
    };
}

export function levels(augments: readonly ISetupAugmentChoice[]): Record<(typeof KINDS)[number], number> {
    const out = Object.fromEntries(KINDS.map((k) => [k, 0])) as Record<(typeof KINDS)[number], number>;
    const seen = new Set<string>();
    for (const a of augments) {
        assert(KINDS.includes(a.kind) && !seen.has(a.kind));
        assert(Number.isSafeInteger(a.value) && a.value >= 0 && a.value <= CAPS[a.kind]);
        seen.add(a.kind);
        out[a.kind] = a.value;
    }
    return out;
}
const entries = (v: ReturnType<typeof levels>): ISetupAugmentChoice[] =>
    KINDS.filter((k) => v[k] > 0).map((kind) => ({ kind, value: v[kind] }));

export function setupPlans(input: PublicSetupInput, incumbent: readonly ISetupAugmentChoice[]): SetupPlan[] {
    const base = levels(incumbent);
    assert.equal(
        Object.values(base).reduce((a, b) => a + b, 0),
        input.budget,
    );
    const units = input.ownCreatureIds.map((id) => creatureInfo(id)!);
    const ranged = units.filter((u) => u.ranged).length;
    const melee = units.filter((u) => u.melee && !u.ranged).length;
    const magic = units.filter((u) => u.dealsMagicDamage).length;
    const affinity = {
        Armor: 1,
        Might: melee / 6,
        Sniper: ranged / 6,
        Empower: magic / 6,
        Movement: (melee + units.filter((u) => u.canFly).length) / 6,
    };
    const transfer = (target: "Movement" | "Empower" | "Might" | "Sniper", enabled: boolean) => {
        const out = { ...base };
        if (!enabled || out[target] >= CAPS[target]) return out;
        const donors = (["Might", "Sniper", "Empower", "Armor", "Movement"] as const)
            .filter((k) => k !== target && out[k] > (k === "Armor" ? 1 : 0))
            .sort((a, b) => affinity[a] - affinity[b] || KINDS.indexOf(a) - KINDS.indexOf(b));
        if (donors.length) {
            out[donors[0]]--;
            out[target]++;
        }
        return out;
    };
    const budgets = [
        base,
        base,
        base,
        transfer("Movement", true),
        transfer("Empower", magic > 0),
        transfer(ranged >= melee ? "Sniper" : "Might", ranged + melee > 0),
    ];
    const modes: SplitMode[] = [
        "native",
        "halves",
        "singles",
        "native",
        magic > 0 ? "halves" : "native",
        "concentrated",
    ];
    return PLAN_IDS.map((id, i) => {
        const augments = i < 3 ? incumbent.map((a) => ({ ...a })) : entries(budgets[i]);
        assert.equal(
            augments.reduce((s, a) => s + a.value, 0),
            input.budget,
        );
        assert.equal(budgets[i].Placement, base.Placement);
        return { id, augments, splitMode: modes[i], spendChanged: KINDS.some((k) => budgets[i][k] !== base[k]) };
    });
}

export function planSplits(
    units: readonly ITacticalSplitUnit[],
    maximumStacks: number,
    mode: SplitMode,
): A19SupportSplitPlan[] {
    const native = planA19SupportSplits(units, maximumStacks);
    if (mode === "native") return native;
    if (mode === "concentrated") return [];
    const living = units.filter((u) => u.amount > 0);
    const slots = Math.max(0, Math.min(Math.floor(maximumStacks) - living.length, Math.floor(maximumStacks) - 6));
    const priority = ["Magic Dragon:4", "Healer:2", "Wandering Mage:1", "Satyr:2"];
    const targets = priority.flatMap((identity) => {
        const found = living.filter((u) => u.identity === identity);
        return found.length === 1 && !found[0].summoned && Number.isSafeInteger(found[0].amount) && found[0].amount > 1
            ? found
            : [];
    });
    const result: A19SupportSplitPlan[] = [];
    for (const u of targets) {
        if (result.length >= slots) break;
        result.push({
            sourceUnitId: u.id,
            amount: mode === "halves" ? Math.floor(u.amount / 2) : 1,
            role: u.identity.startsWith("Magic Dragon") ? "cover" : "support",
        });
    }
    const selected = new Set(result.map((p) => p.sourceUnitId));
    result.push(...native.filter((p) => !selected.has(p.sourceUnitId)).slice(0, Math.max(0, slots - result.length)));
    assert(result.length <= slots);
    const used = new Map<string, number>();
    for (const p of result) {
        const u = units.find((u) => u.id === p.sourceUnitId)!;
        used.set(u.id, (used.get(u.id) ?? 0) + p.amount);
        assert(p.amount >= 1 && used.get(u.id)! < u.amount);
    }
    return result;
}

export const RESPONSE_IDS = ["fast-engagement", "durable", "ranged-or-magic"] as const;
export function responseScenarios(input: PublicSetupInput) {
    const enemy = input.context.publicOpponentCreatureIds.map((id) => creatureInfo(id)!);
    const moreMagic = enemy.filter((u) => u.dealsMagicDamage).length > enemy.filter((u) => u.ranged).length;
    return [
        { id: RESPONSE_IDS[0], doctrine: 3, artifactT1: 5, artifactT2: 5, plan: 3 },
        { id: RESPONSE_IDS[1], doctrine: 1, artifactT1: 4, artifactT2: 2, plan: 0 },
        { id: RESPONSE_IDS[2], doctrine: 2, artifactT1: moreMagic ? 13 : 10, artifactT2: moreMagic ? 13 : 8, plan: 2 },
    ];
}

export interface SearchDecision {
    selected: number;
    meanGains: number[];
    futureGains: number[][];
    accepted: boolean[];
}
export function chooseSearchPlan(
    scores: readonly (readonly (readonly number[])[])[],
    allowed: readonly number[] = [0, 1, 2, 3, 4, 5],
): SearchDecision {
    assert.equal(scores.length, 6);
    assert(allowed.includes(0) && allowed.every((i) => i >= 0 && i < 6));
    for (const p of scores) {
        assert.equal(p.length, 3);
        for (const h of p) assert.equal(h.length, 2);
        assert(p.flat().every((x) => x === 0 || x === 0.5 || x === 1));
    }
    const futureGains = scores.map((p) => [0, 1].map((f) => p.reduce((s, h, i) => s + h[f] - scores[0][i][f], 0) / 3));
    const meanGains = futureGains.map((g) => (g[0] + g[1]) / 2);
    const accepted = meanGains.map(
        (g, i) => i > 0 && allowed.includes(i) && g >= SEARCH_MARGIN && futureGains[i].every((x) => x > 0),
    );
    let selected = 0;
    for (const i of allowed) if (accepted[i] && (selected === 0 || meanGains[i] > meanGains[selected])) selected = i;
    return { selected, meanGains, futureGains, accepted };
}

