export function prepareNative(
    config: any,
    seed: number,
    candidateTeam: number,
    options: { ownPlan?: number; opponentPlan?: number; incumbentSpending?: boolean; matchedGeometry?: any } = {},
) {
    assertPackageIdentity();
    config = structuredClone(config);
    for (const side of ["green", "red"])
        assert.deepEqual(config[side + "PublicOpponentCreatures"], [...new Set(config[side + "RevealedCreatures"])]);
    // Construct the process singleton before entering the match RNG scope. Its first construction
    // draws an unused default map; letting that consume this match's RNG makes cold workers differ.
    FightStateManager.getInstance();
    const specs = [config.roster, config.redRoster],
        rosters: number[][] = [],
        amounts = new Map<number, number>();
    for (const roster of specs) {
        const ids: number[] = [];
        for (const unit of roster) {
            const id = creatureIdForName(unit.creatureName);
            assert(id !== undefined);
            assert.equal(
                unit.amount,
                amountForCreatureExperienceBudget(id, 1000, 10),
                "Ranked stack experience differs",
            );
            if (!ids.includes(id)) ids.push(id);
            amounts.set(id, (amounts.get(id) ?? 0) + unit.amount);
        }
        rosters.push(ids);
    }
    assert(
        rosters[0].every((id) => !rosters[1].includes(id)),
        "Cohort armies must not overlap",
    );
    const draftReveals = { green: [...config.greenRevealedCreatures], red: [...config.redRevealedCreatures] };
    config.greenPublicOpponentCreatures = [...rosters[1]];
    config.redPublicOpponentCreatures = [...rosters[0]];
    assert.equal(RANKED_PLACEMENT_OPTIONS.hideOpponentRosterDuringSetup, false);
    setDeterministicRandomSource(makeRng(seed));
    const manager = new PlaySessionManager({
        nowMillis: () => 1000,
        aiTakeoverMs: 999999,
        persistJournal: false,
        startTimers: false,
    });
    try {
        const { gameId } = manager.createGame({
            gameId: `sim-${config.seed}`,
            leftPlayerId: "L",
            rightPlayerId: "R",
            lowerCreatureIds: rosters[0],
            upperCreatureIds: rosters[1],
            unitAmount: 1,
            unitAmountForCreature: (id) => amounts.get(id),
            gridType: config.gridType,
            ...RANKED_PLACEMENT_OPTIONS,
            leftKnownOpponentCreatureIds: draftReveals.green,
            rightKnownOpponentCreatureIds: draftReveals.red,
            leftArtifactTier1: config.greenArtifactT1,
            leftArtifactTier2: config.greenArtifactT2,
            rightArtifactTier1: config.redArtifactT1,
            rightArtifactTier2: config.redArtifactT2,
            lowerDoctrine: config.greenDoctrine,
            upperDoctrine: config.redDoctrine,
        });
        const session = (manager as any).sessions.get(gameId);
        session.fightProperties.setSynergyVariants(config.synergyVariants);
        const setupReceipts: any[] = [];
        const planByTeam = new Map<number, any>();
        const policyForTeam = session.setupPolicyForTeam.bind(session);
        session.setupPolicyForTeam = (team: number) => {
            const base = policyForTeam(team);
            return {
                ...base,
                pickAugments: (budget: number, own: number[], context: any) => {
                    const incumbent = base.pickAugments(budget, own, context);
                    const visible = publicSetupInput(own, budget, team, context);
                    const choices = setupPlans(visible, incumbent);
                    const index = team === candidateTeam ? (options.ownPlan ?? 0) : (options.opponentPlan ?? 0);
                    assert(index >= 0 && index < PLAN_IDS.length);
                    const plan = choices[index];
                    planByTeam.set(team, { input: visible, choices, selected: index, plan });
                    return team === candidateTeam && options.incumbentSpending ? choices[0].augments : plan.augments;
                },
            };
        };
        for (const team of [2, 1]) {
            const player = session.getPlayerByTeam(team);
            player.aiControlled = true;
            player.persistentAi = true;
            player.aiVersion = "v0.8";
        }
        for (const team of [2, 1]) {
            const player = session.getPlayerByTeam(team);
            const context = session.setupDecisionContext(team);
            const budget = session.fightProperties.getUpgradePoints(team);
            assert.equal(context.opponentRosterVisibility, "complete");
            const publicIds = rosters[team === 2 ? 1 : 0];
            const viewer = manager.getSnapshot(gameId, team === 2 ? "L" : "R");
            assert.equal(viewer.hideOpponentRosterDuringSetup, false);
            assert.equal(viewer.placementStage, 0);
            const enemies = viewer.units.filter((u: any) => u.team !== team);
            assert.equal(enemies.length, publicIds.length);
            assert(enemies.every((u: any) => !u.placed && u.cells.length === 0));
            assert.deepEqual(
                [...context.publicOpponentCreatureIds].sort((a, b) => a - b),
                [...publicIds].sort((a, b) => a - b),
            );
            const policy = session.setupPolicyForTeam(team);
            assert(policy.rangedSetupModelId, "Missing adopted setup policy");
            const augments = policy.pickAugments(budget, rosters[team === 2 ? 0 : 1], context);
            assert.equal(
                augments.reduce((sum: number, a: any) => sum + a.value, 0),
                budget,
            );
            session.commitBotSetupForTeam(player);
            assert(session.botSetupCommittedTeams.has(team) && player.setupReady);
            const getters: any = {
                Placement: "getAugmentPlacementLevel",
                Armor: "getAugmentArmor",
                Might: "getAugmentMight",
                Empower: "getAugmentEmpower",
                Sniper: "getAugmentSniper",
                Movement: "getAugmentMovement",
            };
            for (const [kind, getter] of Object.entries(getters))
                assert.equal(
                    session.fightProperties[getter as string](team),
                    augments.find((a: any) => a.kind === kind)?.value ?? 0,
                    "Native funded augment choice differs",
                );
            config[team === 2 ? "greenAugments" : "redAugments"] = structuredClone(augments);
            const synergies = session.setupSynergiesForTeam(team);
            config[team === 2 ? "greenSynergies" : "redSynergies"] = structuredClone(synergies);
            setupReceipts.push({
                team,
                budget,
                context,
                model: policy.rangedSetupModelId,
                augments,
                synergies,
                committedByNativeBotMethod: true,
            });
        }
        session.rebuildPlacementZones();
        session.refreshSynergies();
        session.tryAdvanceSetupIfReady();
        assert.equal(session.placementStage, 1);
        const teams: any = {},
            placementCalls: any[] = [],
            splitCalls: any[] = [],
            appliedSplits: any[] = [];
        const splitPlanner = session.planAiTacticalSplits.bind(session);
        session.planAiTacticalSplits = (team: number) => {
            const original = splitPlanner(team);
            const units = session.unitsHolder
                .getAllAllies(team)
                .filter((u: any) => !u.isDead())
                .map(tacticalSplitUnitFromUnit);
            const maximumStacks = session.fightProperties.getNumberOfUnitsAvailableForPlacement(team);
            const selected = planByTeam.get(team);
            assert(selected, "Missing public setup plan");
            const plans = planSplits(units, maximumStacks, selected.plan.splitMode);
            splitCalls.push({ team, maximumStacks, units, original, plans });
            return plans;
        };
        const apply = session.applySessionAction.bind(session);
        session.applySessionAction = (action: any, ...args: any[]) => {
            const result = apply(action, ...args);
            if (action.type === "split_unit") {
                appliedSplits.push({
                    action,
                    completed: result.completed,
                    rejectionReason: result.rejectionReason,
                    events: result.events,
                });
                assert(result.completed, "Native split rejected; preserve case");
            }
            return result;
        };
        const original = session.applyLearnedFinalPlacement.bind(session);
        session.applyLearnedFinalPlacement = (team: number, ...args: any[]) => {
            const before = anchors(session.unitsHolder.getAllAllies(team)),
                events = original(team, ...args);
            const units = session.unitsHolder.getAllAllies(team),
                baseline = anchors(units);
            let desired = baseline;
            if (team === candidateTeam && options.matchedGeometry) {
                const fixed = options.matchedGeometry;
                assert.deepEqual(
                    units.map((u: any) => [
                        u.getName(),
                        u.getAmountAlive(),
                        u.getFootprintWidth(),
                        u.getFootprintHeight(),
                    ]),
                    fixed.bodies,
                );
                desired = fixed.positions;
                session.clearPlacedTeamForStrategy(team);
                for (let i = 0; i < units.length; i++) {
                    const u = units[i],
                        cells = session.aiFootprintForCell(u, desired[i]);
                    assert(session.canPlaceUnit(u, cells, team), "Matched incumbent-spend formation is not legal");
                    const result = session
                        .createActionEngine()
                        .apply({ type: "place_unit", unitId: u.getId(), unitName: u.getName(), team, cells });
                    assert(result.completed, "Matched incumbent-spend formation rejected");
                }
            }
            const after = anchors(units);
            assert.deepEqual(after, desired, "Native Dragon rear choice differs");
            placementCalls.push({
                team,
                version: session.getPlayerByTeam(team).aiVersion,
                changed: hash(before) !== hash(after),
                events: events.length,
                baseline,
                desired,
                applied: after,
            });
            return events;
        };
        const actual = JSON.parse(JSON.stringify(config));
        // Freeze the opponent's native setup before the candidate's intervention in every arm.
        // This is an ordinary legal placement order and prevents a split consuming its RNG stream.
        for (const team of [3 - candidateTeam, candidateTeam]) {
            session.rePlaceTeam(team, true);
            const units = session.unitsHolder.getAllAllies(team),
                prior = specs[team === 2 ? 0 : 1];
            const roster = units.map((u: any) => ({
                ...prior.find((s: any) => s.creatureName === u.getName()),
                amount: u.getAmountAlive(),
                initialSpellEntries: [...u.getAllProperties().spells],
            }));
            assert.deepEqual(totals(roster), totals(prior), "Native split lost or added creatures");
            assert(
                units.every((u: any) => session.isUnitPlaced(u)),
                "Unplaced native unit",
            );
            actual[team === 2 ? "roster" : "redRoster"] = roster;
            teams[team] = {
                version: session.getPlayerByTeam(team).aiVersion,
                bodies: units.map((u: any) => [
                    u.getName(),
                    u.getAmountAlive(),
                    u.getFootprintWidth(),
                    u.getFootprintHeight(),
                ]),
                positions: anchors(units),
                kits: units.map((u: any) => ({
                    name: u.getName(),
                    amount: u.getAmountAlive(),
                    power: u.getStackPower(),
                    spells: u.getSpells().map((s: any) => [s.getName(), s.getAmount()]),
                })),
                barrels: session.grid
                    .getArtifactBarrels(team)
                    .map((b: any) => ({ team: b.team, index: b.index, cell: { ...b.cell } }))
                    .sort((a: any, b: any) => a.index - b.index),
            };
        }
        assert.equal(placementCalls.length, 2);
        return {
            teams,
            setupReceipts,
            rankedPlacementOptions: RANKED_PLACEMENT_OPTIONS,
            publicPlans: Object.fromEntries(planByTeam),
            draftReveals,
            config: actual,
            placementCalls,
            splitCalls,
            appliedSplits,
            terrain: session.grid.getScatteredMountainsStanding(),
        };
    } finally {
        manager.stop();
        setDeterministicRandomSource(undefined);
    }
}

export function fightNative(opening: any, combatSeed: number, hooks: any = {}, locked = false) {
    assertPackageIdentity();
    const drivers = new Set<any>(),
        old = SearchDriver.prototype.appliesTo,
        searchUses: Record<string, number> = {};
    SearchDriver.prototype.appliesTo = function (version: string, team: any) {
        const result = old.call(this, version, team);
        if (result) {
            assert.equal(version, "v0.8");
            searchUses[team] = (searchUses[team] ?? 0) + 1;
        }
        if (getA19NeuralState(this)) drivers.add(this);
        return result;
    };
    let nativeDecisions = 0;
    const turns = createHash("sha256"),
        events = createHash("sha256");
    const strategy = (team: number) => {
        const data = opening.teams[team],
            base = createAIStrategy(data.version);
        assert(base);
        return {
            version: base.version,
            decideTurn: (u: any, c: any) => base.decideTurn(u, c),
            placeArmy(units: any[]) {
                assert.deepEqual(
                    units.map((u) => [u.getName(), u.getAmountAlive(), u.getFootprintWidth(), u.getFootprintHeight()]),
                    data.bodies,
                );
                return new Map(units.map((u, i) => [u.getId(), data.positions[i]]));
            },
        };
    };
    try {
        const result = withScopedAIEnvironment(
            {
                V08_A19_SEARCH_ENV_OVERRIDES: JSON.stringify(
                    locked ? { ...environment, SEARCH_A19_NEURAL_TIES: "0" } : environment,
                ),
                V08_A19_SEARCH: "1",
            },
            () =>
                withSearchEnvironment(environment, () =>
                    runMatch({
                        ...opening.config,
                        greenStrategyOverride: strategy(2),
                        redStrategyOverride: strategy(1),
                        headlessEvents: false,
                        researchA19BaseSearchEnvironment: environment,
                        ...(locked ? { searchEnvOverrideTeams: [opening.candidateTeam] } : {}),
                        searchOfflineDeterministicWork: true,
                        beforeFightStart(ctx: any) {
                            for (const team of [2, 1]) {
                                const units = ctx.unitsHolder.getAllAllies(team),
                                    data = opening.teams[team];
                                assert.deepEqual(
                                    anchors(units),
                                    data.positions,
                                    "Engine silently repaired native placement",
                                );
                                assert.deepEqual(
                                    units.map((u: any) => ({
                                        name: u.getName(),
                                        amount: u.getAmountAlive(),
                                        power: u.getStackPower(),
                                        spells: u.getSpells().map((s: any) => [s.getName(), s.getAmount()]),
                                    })),
                                    data.kits,
                                    "Native split spellbook and stack-power mismatch",
                                );
                                for (const b of ctx.grid.getArtifactBarrels(team))
                                    assert(ctx.grid.unplaceArtifactBarrel(team, b.index));
                                for (const b of data.barrels)
                                    assert(ctx.grid.placeArtifactBarrel(team, b.index, b.cell));
                                assert.deepEqual(
                                    ctx.grid
                                        .getArtifactBarrels(team)
                                        .map((b: any) => ({ team: b.team, index: b.index, cell: { ...b.cell } }))
                                        .sort((a: any, b: any) => a.index - b.index),
                                    data.barrels,
                                );
                            }
                            // Barrel Barricade contributes cells to this terrain view. Compare after applying
                            // the authoritative barrel locations, before the first combat action.
                            assert.deepEqual(
                                canonicalTerrain(ctx.grid.getScatteredMountainsStanding()),
                                canonicalTerrain(opening.terrain),
                                "Native terrain occupancy mismatch",
                            );
                            setDeterministicRandomSource(makeRng(combatSeed));
                        },
                        v09ServerPreflightObserver(o: any) {
                            assert.equal(o.failure, null);
                            nativeDecisions++;
                        },
                        ...hooks,
                        turnExecutionObserver: (r: any) => {
                            turns.update(JSON.stringify(r));
                            hooks.turnExecutionObserver?.(r);
                        },
                        committedEventsObserver: (r: any) => {
                            events.update(JSON.stringify(r));
                            hooks.committedEventsObserver?.(r);
                        },
                    }),
                ),
        );
        const neural = [...drivers].map((d) => getA19NeuralState(d)!);
        // Preserve completed raw outcomes before the caller applies admission. Turn caps/stuck outcomes
        // remain exactly as returned by the fixed engine; never exclude an outcome for being a draw.
        const qualityPassed =
            !result.rejectedGreen &&
            !result.rejectedRed &&
            nativeDecisions === 0 &&
            [1, 2].every((team) => opening.teams[team].version === "v0.8" && searchUses[team] > 0) &&
            neural.length >= 1 &&
            neural.every((s) => s.modelErrors === 0 && s.missingStart === 0);
        return {
            result,
            receipt: {
                qualityPassed,
                nativeDecisions,
                searchUses,
                neural,
                turnHash: turns.digest("hex"),
                eventHash: events.digest("hex"),
                outcomeHash: hash(result),
            },
        };
    } finally {
        SearchDriver.prototype.appliesTo = old;
        setDeterministicRandomSource(undefined);
    }
}

/** Comparison only: preserve every cell and its multiplicity; do not mutate engine ordering. */
export const canonicalTerrain = (cells: readonly { x: number; y: number }[]) =>
    cells.map((c) => ({ ...c })).sort((a, b) => a.x - b.x || a.y - b.y);

